extracted_python_code:
top_bought_tickers = Transactions.WHERE(
    (DATEDIFF("days", date_time, DATETIME('now')) <= 10) & (LOWER(transaction_type) == 'buy')
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

recent_customers_by_month = Customers.WHERE(
    (DATEDIFF("months", join_date, DATETIME('now')) > 0) & (DATEDIFF("months", join_date, DATETIME('now')) <= 6)
).CALCULATE(
    signup_month=JOIN_STRINGS("-", YEAR(join_date), LPAD(MONTH(join_date), 2, "0"))
)

result = recent_customers_by_month.PARTITION(name="monthly_groups", by=(signup_month)).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
).ORDER_BY(signup_month.ASC())

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

distinct_customer_ids = Transactions.WHERE(LOWER(transaction_type) == 'buy').PARTITION(name="distinct_customers", by=customer_id).CALCULATE(
    customer_id=customer_id
)

distinct_ticker_ids = DailyPrices.WHERE(date >= '2023-04-01').PARTITION(name="distinct_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

transactions_in_last_30_days = Transactions.WHERE(
    DATEDIFF("days", date_time, DATETIME('now')) <= 30
).CALCULATE(
    customer_country=customer.country
)

top_countries_by_amount = transactions_in_last_30_days.PARTITION(
    name="countries", 
    by=(customer_country)
).CALCULATE(
    country=customer_country,
    num_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(
    5, 
    by=total_transaction_amount.DESC()
)

result = Broker.CALCULATE(
    lowest_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & 
            (DATEDIFF("days", date, DATETIME('now')) <= 7)
        ).close
    )
)

average_sale_price_q1_2023 = Dealership.CALCULATE(
    asp_q1_2023=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

gpm_2023 = Dealership.CALCULATE(
    total_revenue_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
).CALCULATE(
    gpm=(total_revenue_2023 - total_cost_2023) / total_cost_2023 * 100.0
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') < 7))
)

distinct_customer_ids = Sales.PARTITION(name="customer_groups", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

cash_salesperson_ids = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == 'cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

weekend_payments_to_utility_company = Dealership.CALCULATE(
    num_payments=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == 'utility company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

inventory_cars = InventorySnapshots.WHERE(
    (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
).WHERE(
    RANKING(by=snapshot_date.DESC(), allow_ties=True) == 1
).WHERE(
    is_in_inventory == True
).car.CALCULATE(
    _id,
    make,
    model,
    year
)

ddd_calculation = DermTreatment.Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt)
        ).CALCULATE(
            treatment_duration=DATEDIFF("days", start_dt, end_dt)
        ).WHERE(
            treatment_duration > 0
        ).CALCULATE(
            ddd=tot_drug_amt / treatment_duration
        ).ddd
    )
)

result = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), '@gmail.com') | ENDSWITH(LOWER(email), '@yahoo.com')
        )
    )
)

psoriasis_biologic_patient_count = DermTreatment.CALCULATE(
    num_patients=NDISTINCT(
        Treatments.WHERE(
            (LOWER(diagnosis.diag_name) == 'psoriasis vulgaris') & 
            (LOWER(drug.drug_type) == 'biologic')
        ).patient.patient_id
    )
)

alice_treatments_in_last_6_months = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    six_months_ago=DATETIME('now', 'start of month', '-6 months')
).CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(LOWER(first_name) == 'alice').treatments_received.WHERE(
            (start_dt >= six_months_ago) & (start_dt < start_of_current_month)
        )
    )
)

avg_weight_drugalin = DermTreatment.Drugs.WHERE(LOWER(drug_name) == 'drugalin').CALCULATE(
    average_weight=AVG(treatments_used_in.patient.weight_kg)
)

cohort_avg_weight = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(LOWER(gender) == 'male').weight_kg)
)

npi_by_year = DermTreatment.Patients.CALCULATE(
    first_treatment_year=YEAR(MIN(treatments_received.start_dt))
).PARTITION(
    name="yearly_groups", by=first_treatment_year
).CALCULATE(
    year=first_treatment_year,
    num_new_patients=COUNT(Patients)
).ORDER_BY(year.ASC()).CALCULATE(
    year=year,
    num_new_patients=num_new_patients,
    NPINPI=num_new_patients - PREV(num_new_patients, by=year.ASC(), default=0)
)

overall_d7d100pir = DermTreatment.CALCULATE(
    avg_pasi_d7=AVG(Outcomes.WHERE(PRESENT(day7_pasi_score) & PRESENT(day100_pasi_score)).day7_pasi_score),
    avg_pasi_d100=AVG(Outcomes.WHERE(PRESENT(day7_pasi_score) & PRESENT(day100_pasi_score)).day100_pasi_score)
).CALCULATE(
    d7d100pir=(avg_pasi_d100 - avg_pasi_d7) / avg_pasi_d7 * 100.0
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((LOWER(gender) == 'female') & (LOWER(ins_type) == 'private')))
)

result = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) &
            (MONTH(reported_dt) == MONTH(treatment.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

distinct_doctor_states = DermTreatment.Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == 'biologic')) == 1
).PARTITION(
    name="states", by=loc_state
).CALCULATE(
    state=loc_state
)

recent_psoriasis_treatments = DermTreatment.CALCULATE(
    treatment_count=COUNT(
        Treatments.WHERE(
            (LIKE(LOWER(diagnosis.diag_name), '%psoriasis%')) &
            (PRESENT(drug.fda_appr_dt)) &
            (PRESENT(end_dt)) &
            (DATEDIFF("months", end_dt, DATETIME('now')) <= 6)
        )
    )
)

avg_age_of_patients = DermTreatment.CALCULATE(
    avg_patient_age=AVG(
        Patients.WHERE(
            (LOWER(gender) == 'male') & (LOWER(ins_type) == 'private')
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age_in_years
    )
)

result = Merchants.CALCULATE(
    merchant_name=name,
    cpur=NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER("successful")
        ).WHERE(
            PRESENT(coupon_id)
        ).coupon_id
    ) / NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER("successful")
        ).txid
    )
)

result = Ewallet.CALCULATE(
    num_transactions=COUNT(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        )
    ),
    total_amount=SUM(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        ).amount
    )
)

lub_per_user = Users.CALCULATE(
    user_id=uid,
    latest_user_balance=balances.WHERE(
        RANKING(by=updated_at.DESC(), per="Users") == 1
    ).SINGULAR().balance
)

user_marketing_preference = Ewallet.Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

user_session_durations = Ewallet.UserSessions.WHERE(
    (session_start_ts >= "2023-06-01") & (session_start_ts < "2023-06-08")
).CALCULATE(
    duration_in_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
).PARTITION(
    name="sessions_by_user", by=(user_id)
).CALCULATE(
    user_id=user_id,
    total_duration=ROUND(SUM(UserSessions.duration_in_seconds), 0)
).ORDER_BY(total_duration.DESC())

tuc_in_past_month = Ewallet.CALCULATE(
    tuc=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

result = Ewallet.Merchants.CALCULATE(
    merchant_creation_year=YEAR(created_at),
    merchant_creation_month=MONTH(created_at)
).CALCULATE(
    merchant_id=mid,
    merchant_name=name,
    num_coupons=COUNT(
        coupons.WHERE(
            (YEAR(created_at) == merchant_creation_year) & (MONTH(created_at) == merchant_creation_month)
        )
    )
).TOP_K(1, by=num_coupons.DESC())

distinct_receiving_merchants = Transactions.WHERE(receiver_type == 1).PARTITION(name="merchants", by=(receiver_id)).CALCULATE(
    merchant_id=receiver_id
)

distinct_transaction_notification_users = Notifications.WHERE(
    LOWER(notification_type) == 'transaction'
).PARTITION(
    name='distinct_users', by=user_id
).CALCULATE(
    user_id
)

result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(
        Merchants.WHERE(
            (LOWER(status) == 'active') & 
            (CONTAINS(LOWER(category), 'retail'))
        ).balances.WHERE(
            updated_at >= DATETIME('now', 'start of day')
        ).balance
    )
)

# Find the earliest snapshot date in 2023
earliest_2023_snapshot = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).TOP_K(1, by=snapshot_date.ASC())

# Calculate the average limits for that earliest date
result = Ewallet.CALCULATE(
    avg_daily_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_2023_snapshot.SINGULAR().snapshot_date
        ).tx_limit_daily
    ),
    avg_monthly_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_2023_snapshot.SINGULAR().snapshot_date
        ).tx_limit_monthly
    )
)

session_duration_by_device = Ewallet.UserSessions.CALCULATE(
    session_duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
).PARTITION(
    name="sessions_by_device", 
    by=(device_type)
).CALCULATE(
    device_type=device_type,
    average_duration_in_seconds=AVG(UserSessions.session_duration_seconds)
)

users_without_first_year_notifications = Users.CALCULATE(
    signup_anniversary=DATETIME(created_at, '+1 year')
).WHERE(
    HASNOT(notifications.WHERE(created_at <= signup_anniversary)) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
